FUNCTION_BLOCK FB_TandemColdMill_TensionRollGap
(*
====================================================================================================
  LUMINA ADVANCED INDUSTRIAL CYBER-PHYSICAL AUTOMATION KERNEL - TANDEM COLD MILL DIVISION
  IEC 61131-3 COMPLIANT CONTROLLER FOR CONTINUOUS 5-STAND COLD ROLLING TANDEM MILL
  DOMAIN: INTER-STAND STRIP TENSION REGULATION & DUAL-AXIS HYDRAULIC ROLL GAP POSITION MODULATION
====================================================================================================
  Architectural & Engineering Specifications:
    1. Triple Modular Redundant (2oo3 TMR) Tensiometer Load Cell Voting & Fault Detection:
       - Triplicate load cells (A, B, C) on deflector measuring roll beneath strip passline.
       - Discrepancy analysis: pairwise checks (|A-B|, |B-C|, |C-A| <= delta_max_discrepancy).
       - Median-select voting engine with automatic, bumpless channel isolation on drift.
       - Degraded state handling: 2oo3 -> 1oo2 on single channel fault; 1oo2 -> degraded hold
         with AGC freeze and Level-2 supervisory escalation on dual channel fault.
    2. Dynamic Gaugemeter (BISRA AGC) with Mill Spring & Roll Eccentricity Compensation:
       - Cold mill housing structural stiffness modulus: M_mill = 4250.0 ton/mm.
       - Gaugemeter equation: delta_h = delta_s + (delta_F / M_mill) - thermal/oil corrections.
       - Forward slip and backward slip kinematic coupling with strip transport speed.
    3. Multivariable Decoupled State-Space Observer & Model Predictive Tension Trim (MPC):
       - State vector: x = [delta_tension, delta_thickness, delta_slip, int_tension_error]^T.
       - Discrete-time Luenberger state observer reconstructing unmeasured forward slip.
       - Coordinated decoupling between hydraulic roll gap (gauge) and motor speed (tension).
    4. Dual-Axis High-Response Electrohydraulic Position Servo Regulation:
       - High-speed Moog/Rexroth servo valve spool control with square-root pressure compensation.
       - Independent Drive-Side (DS) and Operator-Side (OS) cylinder position loops.
       - Roll tilt and leveling regulation eliminating strip wedge, camber, and differential stress.
    5. SIL-3 Safety Interlocks, Anti-Slack, Over-Force Protection & Graceful Degradation:
       - Deterministic 8-state sequence machine: IDLE -> CALIBRATE -> THREAD -> BITE -> RUN
         -> DEGRADED -> TAILOUT -> ABORT.
       - Fast hydraulic dump valves, anti-slack tension drop abort, and over-force safety trip.
====================================================================================================
*)
VAR_INPUT
    bEnableMill                 : BOOL;     (* Master mill stand automation enable signal [1=Run, 0=Stop] *)
    bEStopTripped               : BOOL;     (* Hardwired SIL-3 emergency stop circuit [0=TRIPPED, 1=NORMAL_OK] *)
    bAutoGaugeControlEnable     : BOOL;     (* BISRA AGC closed-loop thickness regulation active command *)
    bLooperTensionMode          : BOOL;     (* Strip transport mode: 0=Looper-less speed trim, 1=Hydraulic looper *)
    bAckAlarms                  : BOOL;     (* Operator alarm acknowledgment and reset push-button *)
    rTensionLoadCell_A_kN       : REAL;     (* Tensiometer transducer Channel A raw strip tension [kN] *)
    rTensionLoadCell_B_kN       : REAL;     (* Tensiometer transducer Channel B raw strip tension [kN] *)
    rTensionLoadCell_C_kN       : REAL;     (* Tensiometer transducer Channel C raw strip tension [kN] *)
    rStripSpeed_FPM_mpm         : REAL;     (* Inter-stand linear strip line velocity [m/min] *)
    rRollGapMeasure_DS_mm       : REAL;     (* Drive side hydraulic cylinder position transducer LVDT [mm] *)
    rRollGapMeasure_OS_mm       : REAL;     (* Operator side hydraulic cylinder position transducer LVDT [mm] *)
    rHydraulicSupplyPress_bar   : REAL;     (* High-pressure HPU rail accumulator supply pressure [bar] *)
    rSeparatingForce_DS_ton     : REAL;     (* Drive side load cell roll separating force measurement [ton] *)
    rSeparatingForce_OS_ton     : REAL;     (* Operator side load cell roll separating force measurement [ton] *)
    rTargetTension_kN           : REAL;     (* Supervisory Level-2 target inter-stand strip tension setpoint [kN] *)
    rTargetRollGap_mm           : REAL;     (* Supervisory Level-2 target nominal roll gap setting [mm] *)
    rStripWidth_mm              : REAL;     (* Strip nominal material width for rolling plastic modulus [mm] *)
    rStripThickness_mm          : REAL;     (* Strip entry nominal thickness reference dimension [mm] *)
    rSampleTime_s               : REAL;     (* Deterministic PLC cyclic execution task sample time [s] *)
END_VAR

VAR_OUTPUT
    rServoValveFlow_DS_pct      : REAL;     (* Drive side electrohydraulic servo valve drive current spool command [-100.0% to +100.0%] *)
    rServoValveFlow_OS_pct      : REAL;     (* Operator side electrohydraulic servo valve drive current spool command [-100.0% to +100.0%] *)
    rStandSpeedCorrection_pct   : REAL;     (* Inter-stand main drive motor angular velocity trim reference [-15.0% to +15.0%] *)
    rCalculatedTension_kN       : REAL;     (* 2oo3 TMR validated, voted, and filtered inter-stand strip tension [kN] *)
    rTotalRollForce_ton         : REAL;     (* Instantaneous total roll separating force DS + OS [ton] *)
    rStripGaugeError_mm         : REAL;     (* BISRA AGC estimated strip exit thickness deviation [mm] *)
    wMillStatusWord             : WORD;     (* Packed system automation status register bitfield *)
    wMillAlarmWord              : WORD;     (* Packed safety, hydraulic, and process anomaly alarm register *)
    bInterstandTensionStable    : BOOL;     (* Strip tension within strict process tolerance band (+/-2.5%) *)
    bRollGapInPosition          : BOOL;     (* Hydraulic cylinders settled within tolerance window (+/-0.002 mm) *)
    bTMRDegradedMode            : BOOL;     (* TMR sensor voting discrepancy active - degraded 1oo2/1oo1 mode *)
END_VAR

VAR
    (* --- State Machine Control & Sequencing --- *)
    iMillState                  : INT := 0; (* Primary sequencing state variable *)
    iPreviousState              : INT := 0; (* State transition history tracker *)
    rStateTime_s                : REAL := 0.0; (* Elapsed dwell time in active state [s] *)

    (* --- 2oo3 TMR Tensiometer Voting Logic Variables --- *)
    bSensorFail_A               : BOOL := FALSE; (* Load cell A fault latch *)
    bSensorFail_B               : BOOL := FALSE; (* Load cell B fault latch *)
    bSensorFail_C               : BOOL := FALSE; (* Load cell C fault latch *)
    rDev_AB                     : REAL := 0.0;   (* Channel deviation |A - B| [kN] *)
    rDev_BC                     : REAL := 0.0;   (* Channel deviation |B - C| [kN] *)
    rDev_CA                     : REAL := 0.0;   (* Channel deviation |C - A| [kN] *)
    rDiscrepancyTimer_s         : REAL := 0.0;   (* Sensor disagreement filter timer [s] *)
    rVotedTensionRaw_kN         : REAL := 0.0;   (* Unfiltered median voted tension [kN] *)
    rTensionFilterAcc_kN        : REAL := 0.0;   (* PT-1 low-pass filter accumulator [kN] *)

    (* --- Mill Housing & BISRA AGC Mathematical Parameters --- *)
    c_MillModulus_ton_per_mm    : REAL := 4250.0; (* Cold mill housing structural stiffness M_mill [ton/mm] *)
    rNominalBiteForce_ton       : REAL := 1850.0; (* Baseline reference rolling force tare [ton] *)
    rMillStretch_mm             : REAL := 0.0;    (* Calculated elastic deflection of mill stand housing [mm] *)
    rFilteredRollForce_ton      : REAL := 0.0;    (* Low-pass filtered total separating force [ton] *)
    rAgcCorrection_mm           : REAL := 0.0;    (* Gaugemeter feedback roll gap correction [mm] *)
    rLevelingError_mm           : REAL := 0.0;    (* Differential gap between drive side and operator side [mm] *)
    rLevelingCorrection_mm      : REAL := 0.0;    (* Differential tilt correction command [mm] *)

    (* --- Multivariable Discrete State-Space Observer & MPC Model --- *)
    (* State vector: x_hat = [x1_tens_dev, x2_gauge_dev, x3_slip_dev, x4_int_err]^T *)
    x1_hat_TensionDev_kN        : REAL := 0.0;
    x2_hat_GaugeDev_mm          : REAL := 0.0;
    x3_hat_ForwardSlip_pct      : REAL := 0.0;
    x4_int_TensionError         : REAL := 0.0;

    (* Discrete-time system state transition matrix coefficients (Ts = 2ms) *)
    cA11                        : REAL := 0.9850;
    cA12                        : REAL := -12.4500;
    cA13                        : REAL := 18.2000;
    cA21                        : REAL := 0.00012;
    cA22                        : REAL := 0.8920;
    cA23                        : REAL := -0.0045;
    cA31                        : REAL := 0.00008;
    cA32                        : REAL := 0.0520;
    cA33                        : REAL := 0.9410;

    (* Observer correction injection gains (Luenberger matrix L) *)
    cL1_Tension                 : REAL := 0.1250;
    cL2_Gauge                   : REAL := 0.0180;
    cL3_Slip                    : REAL := 0.0065;

    (* Optimal Multivariable Feedback Control Gains (LQR / MPC Synthesis) *)
    cK_Tension_Prop             : REAL := 0.0450; (* Proportional gain for tension to speed trim [%/kN] *)
    cK_Tension_Int              : REAL := 0.1800; (* Integral gain for tension to speed trim [%/(kN*s)] *)
    cK_Tension_Deriv            : REAL := 0.0025; (* Derivative rate damping gain [%*s/kN] *)
    cK_Gap_Prop                 : REAL := 1.2500; (* Proportional gain for hydraulic gap position [mm/mm] *)
    cK_Gap_Int                  : REAL := 0.8500; (* Integral gain for hydraulic gap position [mm/(mm*s)] *)
    cK_CrossCoupling            : REAL := 0.00085;(* Cross-coupling compensation from tension into gap [mm/kN] *)

    (* --- Hydraulic Cylinder Positioning PID Integrators & Spool Linearization --- *)
    rIntegrator_DS_mm           : REAL := 0.0;
    rIntegrator_OS_mm           : REAL := 0.0;
    rPrevError_DS_mm            : REAL := 0.0;
    rPrevError_OS_mm            : REAL := 0.0;
    rHydraulicPresRatio         : REAL := 1.0;
    rSqrtPresFactor             : REAL := 1.0;

    (* --- Engineering Constants & Safety Limits --- *)
    c_MIN_HYD_PRESSURE_BAR      : REAL := 210.0;  (* Minimum allowable hydraulic supply pressure [bar] *)
    c_MAX_TOTAL_FORCE_TON       : REAL := 3400.0; (* Ultimate roll force overload limit [ton] *)
    c_BITING_FORCE_THRESH_TON   : REAL := 450.0;  (* Minimum separating force indicating strip entry [ton] *)
    c_MIN_RUN_TENSION_KN        : REAL := 12.0;   (* Strip slack / breakage tension detection threshold [kN] *)
    c_TMR_MAX_DISCREPANCY_KN    : REAL := 18.0;   (* Allowable load cell channel deviation [kN] *)
    c_MAX_LEVELING_TILT_MM      : REAL := 0.450;  (* Maximum permissible roll tilt wedge limit [mm] *)
    c_SPEED_TRIM_LIMIT_PCT      : REAL := 12.0;   (* Maximum motor speed trim dynamic authority [%] *)
    c_SERVO_SPOOL_MAX_PCT       : REAL := 100.0;  (* Maximum hydraulic servo valve command clamp [%] *)

    (* --- Internal Process Variables --- *)
    rTensionError_kN            : REAL := 0.0;
    rTensionErrorRate           : REAL := 0.0;
    rPrevTensionError_kN        : REAL := 0.0;
    rTargetGap_DS_mm            : REAL := 0.0;
    rTargetGap_OS_mm            : REAL := 0.0;
    rGapError_DS_mm             : REAL := 0.0;
    rGapError_OS_mm             : REAL := 0.0;
    rGapDeriv_DS                : REAL := 0.0;
    rGapDeriv_OS                : REAL := 0.0;
    rRawServoCmd_DS             : REAL := 0.0;
    rRawServoCmd_OS             : REAL := 0.0;
    rRawSpeedTrim               : REAL := 0.0;
    bStripInBite                : BOOL := FALSE;
    bEmergencyAbortActive       : BOOL := FALSE;
END_VAR

(* ================================================================================================ *)
(*                                    1. SAFETY & CRITICAL INTERLOCKS                              *)
(* ================================================================================================ *)
IF NOT bEStopTripped THEN
    iMillState := 999; (* Immediate Emergency Safe Abort *)
    bEmergencyAbortActive := TRUE;
    wMillAlarmWord := wMillAlarmWord OR 16#0001; (* Bit 0: Emergency Stop Tripped *)
END_IF;

IF rHydraulicSupplyPress_bar < c_MIN_HYD_PRESSURE_BAR THEN
    wMillAlarmWord := wMillAlarmWord OR 16#0002; (* Bit 1: Hydraulic Pressure Low *)
    IF iMillState >= 20 THEN
        iMillState := 999;
    END_IF;
ELSE
    IF bAckAlarms THEN
        wMillAlarmWord := wMillAlarmWord AND NOT 16#0002;
    END_IF;
END_IF;

(* Total Roll Force Calculation and Tare *)
rTotalRollForce_ton := rSeparatingForce_DS_ton + rSeparatingForce_OS_ton;
IF rTotalRollForce_ton > c_MAX_TOTAL_FORCE_TON THEN
    wMillAlarmWord := wMillAlarmWord OR 16#0004; (* Bit 2: Roll Force High-High Alarm *)
    iMillState := 999;
END_IF;

(* ================================================================================================ *)
(*                      2. 2oo3 TRIPLE MODULAR REDUNDANT TENSIOMETER VOTING ENGINE                 *)
(* ================================================================================================ *)
rDev_AB := ABS(rTensionLoadCell_A_kN - rTensionLoadCell_B_kN);
rDev_BC := ABS(rTensionLoadCell_B_kN - rTensionLoadCell_C_kN);
rDev_CA := ABS(rTensionLoadCell_C_kN - rTensionLoadCell_A_kN);

(* Channel Discrepancy Evaluation with Integrator Window *)
IF (rDev_AB > c_TMR_MAX_DISCREPANCY_KN) OR 
   (rDev_BC > c_TMR_MAX_DISCREPANCY_KN) OR 
   (rDev_CA > c_TMR_MAX_DISCREPANCY_KN) THEN
    rDiscrepancyTimer_s := rDiscrepancyTimer_s + rSampleTime_s;
ELSE
    rDiscrepancyTimer_s := MAX(0.0, rDiscrepancyTimer_s - rSampleTime_s);
END_IF;

IF rDiscrepancyTimer_s > 0.080 THEN (* 80ms persistence indicates true sensor degradation *)
    wMillAlarmWord := wMillAlarmWord OR 16#0008; (* Bit 3: TMR Discrepancy Active *)
    bTMRDegradedMode := TRUE;

    (* Isolate Outlier Channel Based on Pairwise Residuals *)
    IF (rDev_AB > c_TMR_MAX_DISCREPANCY_KN) AND (rDev_CA > c_TMR_MAX_DISCREPANCY_KN) THEN
        bSensorFail_A := TRUE;
    END_IF;
    IF (rDev_AB > c_TMR_MAX_DISCREPANCY_KN) AND (rDev_BC > c_TMR_MAX_DISCREPANCY_KN) THEN
        bSensorFail_B := TRUE;
    END_IF;
    IF (rDev_BC > c_TMR_MAX_DISCREPANCY_KN) AND (rDev_CA > c_TMR_MAX_DISCREPANCY_KN) THEN
        bSensorFail_C := TRUE;
    END_IF;
END_IF;

IF bAckAlarms THEN
    bSensorFail_A := FALSE;
    bSensorFail_B := FALSE;
    bSensorFail_C := FALSE;
    bTMRDegradedMode := FALSE;
    rDiscrepancyTimer_s := 0.0;
    wMillAlarmWord := wMillAlarmWord AND NOT 16#0008;
END_IF;

(* Median Select 2oo3 / Degraded Voting Logic *)
IF NOT bSensorFail_A AND NOT bSensorFail_B AND NOT bSensorFail_C THEN
    (* All three sensors healthy: Mathematical Median Select *)
    IF (rTensionLoadCell_A_kN >= rTensionLoadCell_B_kN) THEN
        IF (rTensionLoadCell_B_kN >= rTensionLoadCell_C_kN) THEN
            rVotedTensionRaw_kN := rTensionLoadCell_B_kN;
        ELSIF (rTensionLoadCell_A_kN <= rTensionLoadCell_C_kN) THEN
            rVotedTensionRaw_kN := rTensionLoadCell_A_kN;
        ELSE
            rVotedTensionRaw_kN := rTensionLoadCell_C_kN;
        END_IF;
    ELSE
        IF (rTensionLoadCell_A_kN >= rTensionLoadCell_C_kN) THEN
            rVotedTensionRaw_kN := rTensionLoadCell_A_kN;
        ELSIF (rTensionLoadCell_B_kN <= rTensionLoadCell_C_kN) THEN
            rVotedTensionRaw_kN := rTensionLoadCell_B_kN;
        ELSE
            rVotedTensionRaw_kN := rTensionLoadCell_C_kN;
        END_IF;
    END_IF;
ELSIF bSensorFail_A AND NOT bSensorFail_B AND NOT bSensorFail_C THEN
    rVotedTensionRaw_kN := 0.5 * (rTensionLoadCell_B_kN + rTensionLoadCell_C_kN);
ELSIF bSensorFail_B AND NOT bSensorFail_A AND NOT bSensorFail_C THEN
    rVotedTensionRaw_kN := 0.5 * (rTensionLoadCell_A_kN + rTensionLoadCell_C_kN);
ELSIF bSensorFail_C AND NOT bSensorFail_A AND NOT bSensorFail_B THEN
    rVotedTensionRaw_kN := 0.5 * (rTensionLoadCell_A_kN + rTensionLoadCell_B_kN);
ELSE
    (* Multiple failures: 1oo1 fallback to available channel with safety lock *)
    IF NOT bSensorFail_A THEN
        rVotedTensionRaw_kN := rTensionLoadCell_A_kN;
    ELSIF NOT bSensorFail_B THEN
        rVotedTensionRaw_kN := rTensionLoadCell_B_kN;
    ELSE
        rVotedTensionRaw_kN := rTensionLoadCell_C_kN;
    END_IF;
    wMillAlarmWord := wMillAlarmWord OR 16#0010; (* Bit 4: TMR Critical Dual Failure *)
END_IF;

(* First-Order Butterworth / PT-1 Low-Pass Filter on Voted Tension (tau = 15ms) *)
rCalculatedTension_kN := rCalculatedTension_kN + (rSampleTime_s / 0.015) * (rVotedTensionRaw_kN - rCalculatedTension_kN);

(* ================================================================================================ *)
(*               3. DYNAMIC BISRA AGC & MILL HOUSING STRETCH COMPENSATION                          *)
(* ================================================================================================ *)
(* Low-pass filter roll force signal to eliminate roll eccentricity ripple *)
rFilteredRollForce_ton := rFilteredRollForce_ton + (rSampleTime_s / 0.025) * (rTotalRollForce_ton - rFilteredRollForce_ton);

(* Mill housing elasticity modulus calculation *)
rMillStretch_mm := rFilteredRollForce_ton / c_MillModulus_ton_per_mm;

(* Gaugemeter Thickness Error Estimation *)
rStripGaugeError_mm := (0.5 * (rRollGapMeasure_DS_mm + rRollGapMeasure_OS_mm)) + rMillStretch_mm - rTargetRollGap_mm;

(* BISRA AGC Closed-Loop Gap Correction Calculation *)
IF bAutoGaugeControlEnable AND (iMillState = 40) THEN
    rAgcCorrection_mm := -0.85 * rStripGaugeError_mm; (* 85% BISRA compensation factor *)
    (* Clamp maximum AGC stroke authority to prevent chatter *)
    rAgcCorrection_mm := LIMIT(-0.150, rAgcCorrection_mm, 0.150);
ELSE
    rAgcCorrection_mm := 0.0;
END_IF;

(* Differential Leveling Error (Drive Side vs. Operator Side) *)
rLevelingError_mm := rRollGapMeasure_DS_mm - rRollGapMeasure_OS_mm;
rLevelingCorrection_mm := -0.50 * rLevelingError_mm;
rLevelingCorrection_mm := LIMIT(-c_MAX_LEVELING_TILT_MM, rLevelingCorrection_mm, c_MAX_LEVELING_TILT_MM);

(* ================================================================================================ *)
(*          4. MULTIVARIABLE STATE-SPACE OBSERVER & MODEL PREDICTIVE TENSION TRIM                  *)
(* ================================================================================================ *)
(* Calculate tension tracking error *)
rTensionError_kN := rTargetTension_kN - rCalculatedTension_kN;
rTensionErrorRate := (rTensionError_kN - rPrevTensionError_kN) / MAX(0.0001, rSampleTime_s);
rPrevTensionError_kN := rTensionError_kN;

(* State Observer Update: x_hat(k+1) = A * x_hat(k) + L * (y - y_hat) *)
x1_hat_TensionDev_kN := (cA11 * x1_hat_TensionDev_kN) + (cA12 * x2_hat_GaugeDev_mm) + (cA13 * x3_hat_ForwardSlip_pct) 
                        + (cL1_Tension * rTensionError_kN);
x2_hat_GaugeDev_mm   := (cA21 * x1_hat_TensionDev_kN) + (cA22 * x2_hat_GaugeDev_mm) + (cA23 * x3_hat_ForwardSlip_pct) 
                        + (cL2_Gauge * rStripGaugeError_mm);
x3_hat_ForwardSlip_pct := (cA31 * x1_hat_TensionDev_kN) + (cA32 * x2_hat_GaugeDev_mm) + (cA33 * x3_hat_ForwardSlip_pct);

(* Integral Error Accumulation with Dynamic Anti-Windup *)
IF (iMillState = 40) OR (iMillState = 50) THEN
    x4_int_TensionError := x4_int_TensionError + (rTensionError_kN * rSampleTime_s);
    x4_int_TensionError := LIMIT(-150.0, x4_int_TensionError, 150.0);
ELSE
    x4_int_TensionError := 0.0;
END_IF;

(* Coordinated Speed Trim Control Calculation *)
rRawSpeedTrim := (cK_Tension_Prop * rTensionError_kN) 
               + (cK_Tension_Int * x4_int_TensionError) 
               + (cK_Tension_Deriv * rTensionErrorRate)
               - (0.02 * x3_hat_ForwardSlip_pct);

rStandSpeedCorrection_pct := LIMIT(-c_SPEED_TRIM_LIMIT_PCT, rRawSpeedTrim, c_SPEED_TRIM_LIMIT_PCT);

(* ================================================================================================ *)
(*                    5. MULTI-STAGE TANDEM MILL AUTOMATION STATE MACHINE                           *)
(* ================================================================================================ *)
IF iMillState <> iPreviousState THEN
    rStateTime_s := 0.0;
    iPreviousState := iMillState;
ELSE
    rStateTime_s := rStateTime_s + rSampleTime_s;
END_IF;

CASE iMillState OF
    0: (* IDLE / PARKED - Mill de-energized, hydraulic cylinders at open park position *)
        rServoValveFlow_DS_pct := 0.0;
        rServoValveFlow_OS_pct := 0.0;
        rStandSpeedCorrection_pct := 0.0;
        rIntegrator_DS_mm := 0.0;
        rIntegrator_OS_mm := 0.0;
        wMillStatusWord := 16#0001; (* Stand in Idle *)

        IF bEnableMill AND bEStopTripped AND (rHydraulicSupplyPress_bar >= c_MIN_HYD_PRESSURE_BAR) THEN
            iMillState := 10; (* Proceed to Stand Initialization *)
        END_IF;

    10: (* STAND CALIBRATION & LVDT ZEROING *)
        wMillStatusWord := 16#0002; (* Stand Calibrating *)
        rTargetGap_DS_mm := rTargetRollGap_mm + 5.0; (* Preset open gap *)
        rTargetGap_OS_mm := rTargetRollGap_mm + 5.0;

        IF rStateTime_s > 1.5 THEN
            iMillState := 20; (* Calibration complete, proceed to Threading *)
        END_IF;

    20: (* STRIP THREADING & ROLL GAP PRESET *)
        wMillStatusWord := 16#0004; (* Stand Threading *)
        rTargetGap_DS_mm := rTargetRollGap_mm;
        rTargetGap_OS_mm := rTargetRollGap_mm;

        (* Detect strip bite through separating force surge *)
        IF rTotalRollForce_ton >= c_BITING_FORCE_THRESH_TON THEN
            iMillState := 30; (* Strip entry detected *)
        END_IF;

    30: (* STRIP BITING & TENSION BUILDUP *)
        wMillStatusWord := 16#0008; (* Strip In Bite - Building Tension *)
        rTargetGap_DS_mm := rTargetRollGap_mm + rAgcCorrection_mm + rLevelingCorrection_mm;
        rTargetGap_OS_mm := rTargetRollGap_mm + rAgcCorrection_mm - rLevelingCorrection_mm;

        (* Verify positive tension established above slack limit *)
        IF (rCalculatedTension_kN >= c_MIN_RUN_TENSION_KN) AND (rStateTime_s > 0.350) THEN
            iMillState := 40; (* Normal Closed-Loop Running *)
        ELSIF rStateTime_s > 4.0 THEN
            (* Tension failed to build up within timeout - trip slack alarm *)
            wMillAlarmWord := wMillAlarmWord OR 16#0020; (* Bit 5: Tension Buildup Timeout *)
            iMillState := 999;
        END_IF;

    40: (* CLOSED-LOOP RUNNING - FULL AGC & TENSION REGULATION *)
        wMillStatusWord := 16#0010; (* Stand Running in Full Auto *)

        (* Roll gap modulated by nominal reference, BISRA AGC, cross-coupling & leveling *)
        rTargetGap_DS_mm := rTargetRollGap_mm + rAgcCorrection_mm + rLevelingCorrection_mm 
                            - (cK_CrossCoupling * rTensionError_kN);
        rTargetGap_OS_mm := rTargetRollGap_mm + rAgcCorrection_mm - rLevelingCorrection_mm 
                            - (cK_CrossCoupling * rTensionError_kN);

        (* Check for strip breakage / sudden loss of tension *)
        IF rCalculatedTension_kN < c_MIN_RUN_TENSION_KN THEN
            wMillAlarmWord := wMillAlarmWord OR 16#0040; (* Bit 6: Strip Breakage / Tension Loss *)
            iMillState := 999;
        END_IF;

        (* Switch to degraded mode if 2oo3 voting degraded to single transducer *)
        IF (wMillAlarmWord AND 16#0010) <> 0 THEN
            iMillState := 50; (* Degraded Limp Mode *)
        END_IF;

        (* Mill Stop command initiated *)
        IF NOT bEnableMill THEN
            iMillState := 60; (* Tail-out sequence *)
        END_IF;

    50: (* DEGRADED TMR LIMP MODE - Sensor Drift / Fallback Mode *)
        wMillStatusWord := 16#0020; (* Stand in Degraded Mode *)
        (* Freeze AGC to prevent positive feedback runaway, maintain soft tension regulation *)
        rTargetGap_DS_mm := rTargetRollGap_mm + rLevelingCorrection_mm;
        rTargetGap_OS_mm := rTargetRollGap_mm - rLevelingCorrection_mm;
        rStandSpeedCorrection_pct := LIMIT(-5.0, rRawSpeedTrim * 0.60, 5.0);

        IF bAckAlarms AND NOT bTMRDegradedMode THEN
            iMillState := 40; (* Restored to full auto *)
        END_IF;

        IF NOT bEnableMill THEN
            iMillState := 60;
        END_IF;

    60: (* TAIL-OUT PREPARATION & DECOUPLING *)
        wMillStatusWord := 16#0040; (* Stand Tail-out Active *)
        (* Soft de-tensioning to prevent tail whip and work roll damage *)
        rStandSpeedCorrection_pct := 0.0;
        rTargetGap_DS_mm := rTargetRollGap_mm + 1.20;
        rTargetGap_OS_mm := rTargetRollGap_mm + 1.20;

        IF (rTotalRollForce_ton < c_BITING_FORCE_THRESH_TON) OR (rStateTime_s > 3.0) THEN
            iMillState := 0; (* Strip exited stand, return to Idle *)
        END_IF;

    999: (* EMERGENCY SAFE ABORT - FAST CYLINDER OPENING & SPOOL LOCK *)
        wMillStatusWord := 16#8000; (* Emergency Trip Active *)
        rStandSpeedCorrection_pct := 0.0;
        rServoValveFlow_DS_pct := -100.0; (* Fast cylinder open / dump *)
        rServoValveFlow_OS_pct := -100.0;
        x4_int_TensionError := 0.0;
        rIntegrator_DS_mm := 0.0;
        rIntegrator_OS_mm := 0.0;

        IF bAckAlarms AND bEStopTripped AND (rHydraulicSupplyPress_bar >= c_MIN_HYD_PRESSURE_BAR) THEN
            wMillAlarmWord := 16#0000;
            bEmergencyAbortActive := FALSE;
            iMillState := 0; (* Reset back to Idle *)
        END_IF;

ELSE
    iMillState := 999;
END_CASE;

(* ================================================================================================ *)
(*              6. ELECTROHYDRAULIC SERVO VALVE POSITION CONTROLLER (DS & OS)                       *)
(* ================================================================================================ *)
IF iMillState <> 999 THEN
    (* Square-root hydraulic supply pressure normalization *)
    rHydraulicPresRatio := MAX(0.2, rHydraulicSupplyPress_bar / 280.0);
    rSqrtPresFactor := 1.0 / SQRT(rHydraulicPresRatio);

    (* Drive-Side Cylinder Position Closed Loop *)
    rGapError_DS_mm := rTargetGap_DS_mm - rRollGapMeasure_DS_mm;
    rGapDeriv_DS := (rGapError_DS_mm - rPrevError_DS_mm) / MAX(0.0001, rSampleTime_s);
    rPrevError_DS_mm := rGapError_DS_mm;

    rIntegrator_DS_mm := rIntegrator_DS_mm + (cK_Gap_Int * rGapError_DS_mm * rSampleTime_s);
    rIntegrator_DS_mm := LIMIT(-15.0, rIntegrator_DS_mm, 15.0);

    rRawServoCmd_DS := (cK_Gap_Prop * rGapError_DS_mm * 100.0) 
                     + (rIntegrator_DS_mm) 
                     + (0.008 * rGapDeriv_DS);
    rServoValveFlow_DS_pct := LIMIT(-c_SERVO_SPOOL_MAX_PCT, rRawServoCmd_DS * rSqrtPresFactor, c_SERVO_SPOOL_MAX_PCT);

    (* Operator-Side Cylinder Position Closed Loop *)
    rGapError_OS_mm := rTargetGap_OS_mm - rRollGapMeasure_OS_mm;
    rGapDeriv_OS := (rGapError_OS_mm - rPrevError_OS_mm) / MAX(0.0001, rSampleTime_s);
    rPrevError_OS_mm := rGapError_OS_mm;

    rIntegrator_OS_mm := rIntegrator_OS_mm + (cK_Gap_Int * rGapError_OS_mm * rSampleTime_s);
    rIntegrator_OS_mm := LIMIT(-15.0, rIntegrator_OS_mm, 15.0);

    rRawServoCmd_OS := (cK_Gap_Prop * rGapError_OS_mm * 100.0) 
                     + (rIntegrator_OS_mm) 
                     + (0.008 * rGapDeriv_OS);
    rServoValveFlow_OS_pct := LIMIT(-c_SERVO_SPOOL_MAX_PCT, rRawServoCmd_OS * rSqrtPresFactor, c_SERVO_SPOOL_MAX_PCT);
END_IF;

(* Process Performance Verification Flags *)
bInterstandTensionStable := (ABS(rTensionError_kN) <= (0.025 * rTargetTension_kN)) AND (iMillState = 40);
bRollGapInPosition := (ABS(rGapError_DS_mm) <= 0.002) AND (ABS(rGapError_OS_mm) <= 0.002);

END_FUNCTION_BLOCK
